package game;

import com.badlogic.gdx.Input;
import com.badlogic.gdx.backends.headless.mock.input.MockInput;

import java.util.ArrayList;
import java.util.List;

/**
 * ScriptedMockInput exposes a queue of commands to the ApplicationListener one per tick.
 * Each call to {@link #tick()} advances the queue and registers the appropriate
 * keycode(s) with the headless MockInput so that the listener can read them via
 * {@link #isKeyJustPressed(int)} / {@link #isKeyPressed(int)}.
 */
public class ScriptedMockInput extends MockInput {

    /** Per-tick active keys (cleared at next tick). */
    private final List<Integer> activeKeys = new ArrayList<Integer>();

    /** Flags consumed once (per "just pressed" semantics). */
    private final List<Integer> justPressedKeys = new ArrayList<Integer>();

    private final List<String> commands;
    private int index = 0;
    private boolean tickRequested = false;
    private String currentCommand;

    public ScriptedMockInput(List<String> commands) {
        this.commands = new ArrayList<String>(commands);
    }

    /** Returns the current raw command for this tick (may be null if the queue is empty). */
    public String getCurrentCommand() {
        return currentCommand;
    }

    /** True if the current tick has a queued command. */
    public boolean hasCommand() {
        return currentCommand != null;
    }

    /**
     * Advance the queue by one tick. The next command is now exposed via
     * {@link #getCurrentCommand()} and the corresponding keycodes via
     * {@link #isKeyPressed(int)} / {@link #isKeyJustPressed(int)}.
     */
    public void tick() {
        tickRequested = true;
        if (index >= commands.size()) {
            currentCommand = null;
            activeKeys.clear();
            justPressedKeys.clear();
            return;
        }
        currentCommand = commands.get(index++);
        activeKeys.clear();
        justPressedKeys.clear();
        int key = keyFor(currentCommand);
        if (key != -1) {
            activeKeys.add(key);
            justPressedKeys.add(key);
        }
    }

    /** Whether {@link #tick()} has been called at least once since construction. */
    public boolean wasTickRequested() {
        return tickRequested;
    }

    private static int keyFor(String cmd) {
        if (cmd == null) return -1;
        if (cmd.equals("N")) return Input.Keys.UP;
        if (cmd.equals("S")) return Input.Keys.DOWN;
        if (cmd.equals("E")) return Input.Keys.RIGHT;
        if (cmd.equals("W")) return Input.Keys.LEFT;
        if (cmd.equals("PICK")) return Input.Keys.SPACE;
        if (cmd.equals("QUIT")) return Input.Keys.ESCAPE;
        return -1;
    }

    @Override
    public boolean isKeyPressed(int key) {
        for (int i = 0; i < activeKeys.size(); i++) {
            if (activeKeys.get(i) == key) return true;
        }
        return false;
    }

    @Override
    public boolean isKeyJustPressed(int key) {
        for (int i = 0; i < justPressedKeys.size(); i++) {
            if (justPressedKeys.get(i) == key) return true;
        }
        return false;
    }
}
EOF
