            // Wrap the listener so we can observe when the headless main loop terminates.
            ApplicationListener wrapper = new LoopTerminator(game, mainLoopDone);
            app = new HeadlessApplication(wrapper, cfg);
            // Replace Gdx.input with our scripted subclass immediately.
            Gdx.input = scripted;
        }

        // Block the main thread until the headless main-loop thread signals done.
        try {
            mainLoopDone.await();
        } catch (InterruptedException ie) {
            Thread.currentThread().interrupt();
        }
        // Ensure resources are released.
        app.exit();
    }

    private static List<String> readCommands(String path) {
        List<String> out = new ArrayList<String>();
        java.io.BufferedReader br = null;
        try {
            br = new java.io.BufferedReader(
                    new java.io.InputStreamReader(
                            new java.io.FileInputStream(path), "UTF-8"));
            String line;
            while ((line = br.readLine()) != null) {
                String trimmed = line.trim();
                if (trimmed.isEmpty()) continue;
                if (trimmed.startsWith("#")) continue;
                out.add(trimmed);
            }
        } catch (java.io.IOException ioe) {
            throw new RuntimeException("Failed to read commands file: " + path, ioe);
        } finally {
            if (br != null) {
                try { br.close(); } catch (java.io.IOException ignored) { }
            }
        }
        return out;
    }

    /** Wraps a listener so we can fire a latch when the headless main loop stops. */
    private static final class LoopTerminator implements ApplicationListener {
        private final ApplicationListener delegate;
        private final CountDownLatch latch;
        private boolean disposed = false;

        LoopTerminator(ApplicationListener delegate, CountDownLatch latch) {
            this.delegate = delegate;
            this.latch = latch;
        }

        @Override
        public void create() { delegate.create(); }

        @Override
        public void render() {
            try {
                delegate.render();
            } finally {
                if (disposed) latch.countDown();
            }
        }

        @Override
        public void pause() { delegate.pause(); }

        @Override
        public void resize(int width, int height) { delegate.resize(width, height); }

        @Override
        public void resume() { delegate.resume(); }

        @Override
        public void dispose() {
            try {
                delegate.dispose();
            } finally {
                disposed = true;
                latch.countDown();
            }
        }
    }
